SELECT DISTINCTROW Normierung.Elektrolyseur, Normierung.Datum, Normierung.Zeit, Normierung.[I Gesamt], [Normierung]![I Gesamt]/2.72 AS i, Normierung.Cc, Normierung.[t An], Normierung.[t Ka], ([Normierung]![t An]+[Normierung]![t Ka])/2 AS tm, Normierung.Uo, Spannungen.Position, Spannungen.Ui, Spannungen.Uk, [Uo]+(([Ui]-[Uo])*3)/([I Gesamt]/2.72)-0.01*(90-[tm])+0.02*(32-[Cc]) AS Unalt, UnBerVgl([Ui],[i],[tm],[Cc]) AS UnVgl3, AktiRef() AS iRef, AkttKorrektur() AS tKorr, AktcKorrektur() AS cKorr, UnBer([Ui],[i],[tm],[Cc]) AS Un
FROM tblGewDaten, Normierung INNER JOIN Spannungen ON Normierung.Normierung = Spannungen.Normierung
WHERE (((Normierung.Elektrolyseur)=(SELECT Bezeichnung FROM tblElektrolyseurbezeichnung WHERE tblGewDaten.IDElektrolyseurVerteilungUN = tblElektrolyseurbezeichnung.Nr)) AND ((Normierung.Datum)=[tblGewDaten].[DatumVerteilungUN]) AND ((Normierung.[I Gesamt]) Is Not Null) AND ((Normierung.Cc) Is Not Null) AND ((Normierung.[t An]) Is Not Null) AND ((Normierung.[t Ka]) Is Not Null) AND ((Spannungen.Ui)>(Select Umin from tblGewDaten)))
ORDER BY Normierung.Elektrolyseur, Normierung.Datum, Normierung.Zeit, Spannungen.Position;
